<?php if (!defined('ABSPATH')) exit; $identity=ag_section('identity','global'); ?></main><footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="<?php echo esc_url(home_url('/')); ?>"><?php vatan_logo(); ?></a><p><?php echo nl2br(esc_html($identity['footer_body'])); ?></p></div><details class="ag-footer-column" <?php if(vatan_feature('mobile_footer'))echo 'data-footer-accordion'; ?> open><summary><?php ag_text($identity,'footer_products_title'); ?></summary><div><?php if(has_nav_menu('footer_products'))wp_nav_menu(['theme_location'=>'footer_products','container'=>false,'menu_class'=>'ag-footer-menu']);else foreach(vatan_categories() as $slug=>$c) echo '<a href="'.esc_url(vatan_url('products/'.$slug.'/')).'">'.esc_html($c[0]).'</a>'; ?></div></details><details class="ag-footer-column" <?php if(vatan_feature('mobile_footer'))echo 'data-footer-accordion'; ?> open><summary><?php ag_text($identity,'footer_links_title'); ?></summary><div><?php if(has_nav_menu('footer'))wp_nav_menu(['theme_location'=>'footer','container'=>false,'menu_class'=>'ag-footer-menu']);else foreach(['solutions/'=>'همکاری تجاری','media/'=>'رسانه','blog/'=>'مجله تجارت','faq/'=>'پرسش‌های متداول','privacy/'=>'حریم خصوصی'] as $p=>$l) echo '<a href="'.esc_url(vatan_url($p)).'">'.esc_html($l).'</a>'; ?></div></details><details class="ag-footer-column" <?php if(vatan_feature('mobile_footer'))echo 'data-footer-accordion'; ?> open><summary><?php ag_text($identity,'footer_contact_title'); ?></summary><div><a href="tel:<?php echo esc_attr(vatan_option('phone','02191028166')); ?>" dir="ltr"><?php echo esc_html(vatan_option('phone','02191028166')); ?></a><p><?php echo esc_html(vatan_option('address','تهران، سهروردی شمالی، کوچه زمانی، پلاک ۱۱، ساختمان ایلیا، طبقه ۳، واحد ۹')); ?></p><a class="text-link" href="<?php echo esc_url(vatan_url('contact/')); ?>"><?php ag_text($identity,'footer_contact_link'); ?></a><?php if(get_option('vatan_analytics_enabled',false))echo '<button class="ag-privacy-toggle" type="button" data-event-settings>'.esc_html($identity['analytics_settings_label']).'</button>'; ?></div></details></div><div class="footer-bottom"><span>© <?php echo esc_html(wp_date('Y')); ?> <?php ag_text($identity,'rights'); ?></span><span><?php ag_text($identity,'footer_note'); ?></span><?php ag_appearance_mono(); ?></div></div></footer><?php if(vatan_feature('mobile_cta')&&!is_page('media')&&!is_singular('vatan_episode')): ?><div class="mobilebar"><a class="button" href="<?php echo esc_url((is_singular('vatan_product')?add_query_arg(['product_id'=>get_queried_object_id()],vatan_url('inquiry/')):vatan_url('inquiry/'))); ?>"><?php ag_text($identity,'mobile_inquiry_label'); ?></a><a class="button ghost" href="tel:<?php echo esc_attr(vatan_option('phone','02191028166')); ?>"><?php ag_text($identity,'mobile_contact_label'); ?></a></div><?php endif; ?><dialog class="ag-zoom-dialog" aria-label="نمای بزرگ تصویر"><button type="button" aria-label="بستن تصویر">×</button><img alt=""><p></p></dialog><?php if(get_option('vatan_analytics_enabled',false)): ?><div data-event-endpoint="<?php echo esc_url(rest_url('vatan/v1/events')); ?>"></div><aside class="ag-consent-bar" hidden data-analytics-consent role="region" aria-label="رضایت اختیاری آمار"><p><?php ag_text($identity,'analytics_message'); ?></p><div><button type="button" class="button" data-event-choice="yes"><?php ag_text($identity,'analytics_accept'); ?></button><button type="button" class="button ghost" data-event-choice="no"><?php ag_text($identity,'analytics_reject'); ?></button></div></aside><?php endif; wp_footer(); ?></body></html>
